  {
    "id": "must_get_cart",
    "text": "The shopper is obliged to obtain a cart before completing the trip.",
    "abstraction": {},
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "hasCart"
    }
  },
  {
    "id": "exit_with_cart_only",
    "text": "The shopper is prohibited from exiting the store unless they have a cart.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "no_cart_at_item_cell",
    "text": "The shopper is prohibited from having a cart at cell (3,1).",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "at(3,1)",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "no_cart_north_aisle",
    "text": "The shopper is prohibited from taking a cart into the north aisle cells (3,1) and (3,2).",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          {
            "or": [
              "at(3,1)",
              "at(3,2)"
            ]
          }
        ]
      }
    }
  },
  {
    "id": "park_cart_at_3_3",
    "text": "Upon reaching cell (3,3) with a cart, the shopper is obliged to put the cart down there.",
    "abstraction": {},
    "norm": {
      "type": "obligation",
      "trigger": {
        "and": [
          "at(3,3)",
          "hasCart"
        ]
      },
      "discharge": {
        "and": [
          "at(3,3)",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "recover_cart_at_3_3",
    "text": "Upon being at cell (3,3) without a cart, the shopper is obliged to take the cart again before leaving that area.",
    "abstraction": {},
    "norm": {
      "type": "obligation",
      "trigger": {
        "and": [
          "at(3,3)",
          {
            "not": "hasCart"
          }
        ]
      },
      "discharge": {
        "and": [
          "at(3,3)",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "cart_required_outside_north_aisle",
    "text": "The shopper is prohibited from moving without a cart except at cells (3,1), (3,2), and (3,3).",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          {
            "not": {
              "or": [
                "at(3,1)",
                "at(3,2)",
                "at(3,3)"
              ]
            }
          }
        ]
      }
    }
  },
  {
    "id": "interact_at_cart_station",
    "text": "The shopper is obliged to interact at cell (1,7), consistent with taking a cart from that location.",
    "abstraction": {},
    "norm": {
      "type": "obligation",
      "trigger": {
        "and": [
          "at(1,7)",
          {
            "not": "hasCart"
          }
        ]
      },
      "discharge": {
        "and": [
          "at(1,7)",
          "INTERACT"
        ]
      }
    }
  }
]

